sys_script_client.script:
function onLoad() {
    var eventId = g_form.getValue('number');  

    var ga = new GlideAjax('EventDetailsClientUtils');  // Script Include name
    ga.addParam('sysparm_name', 'getEventDetails');
    ga.addParam('sysparm_event_id', eventId);

    ga.getXMLAnswer(function(response) {
        var data = JSON.parse(response);

        if (data.error) {
            g_form.addInfoMessage('Error: ' + data.error);
        } else {
            var message = {
                          'Name: ' : data.name + '--'+
                          'Date: ' + data.date + '--' +
                          'Location: ' + data.location + '--' +
                          'Status: ' + data.status + '--'+
                          'Contact: ' + data.contact + '--' +
                          'Email: ' + data.email
			}
			var ans = JSON.stringify(message);
            g_form.addInfoMessage(ans);
        }
    });
}
